input.sparql:
SELECT ?point ?ts WHERE {
  ?z a brick:Zone ; rdfs:label "Core_top" .
  ?zone2 rdfs:label "Core_top" .
}

SELECT ?sensor ?slabel ?prop ?tsid WHERE {
  ?sensor a brick:TemperatureSensor ; brick:hasPropertySensor ?prop .
  ?prop rdfs:label ?slabel .
  ?zone brick:contains ?sensor .
  FILTER(LCASE(?slabel)="core_top")
}
